import { AuthType, EmbedConfig } from '@thoughtspot/visual-embed-sdk';

/** ThoughtSpot worksheet / model GUID for Search, Muse (AI), and Explore embeds */
export const THOUGHTSPOT_MODEL_ID = 'cd252e5c-b552-49a8-821d-3eadaa049cca';

/** Liveboard GUID for LiveboardEmbed (saved dashboard) */
export const THOUGHTSPOT_LIVEBOARD_ID = 'cd408f8e-6f29-4a14-af5f-ddaf57ee04d2';

/** ThoughtSpot Cloud cluster origin (no trailing slash) */
export const thoughtSpotHost = 'https://se-thoughtspot-cloud.thoughtspot.cloud';

/** Match host app chrome — Apple-style light gray */
export const EMBED_APP_BACKGROUND = '#F2F2F7';

/** Top header height in App layout (see TopHeader) */
export const TOP_HEADER_PX = 56;

/** Usable height for a full-page embed below the top bar */
export const VIEWPORT_LESS_TOP_HEADER = `calc(100vh - ${TOP_HEADER_PX}px)`;

const publicBase = process.env.PUBLIC_URL ?? '';

/** URL to SVG sprite with `<symbol id="rd-icon-spotter">` (ThoughtSpot iconSpriteUrl — not a raw logo) */
export const DATABOT_ICON_URL = `${publicBase}/databot-robot.svg`;

const BRAND_PINK = '#FF2D55';
const BRAND_PINK_LIGHT = '#FFE4EC';
const BRAND_PINK_HOVER = '#FFADC5';

const embedStyleVariables = {
  // Backgrounds
  '--ts-var-root-background': EMBED_APP_BACKGROUND,
  '--ts-var-liveboard-layout-background': EMBED_APP_BACKGROUND,
  '--ts-var-liveboard-header-background': '#ffffff',
  '--ts-var-liveboard-tile-background': '#ffffff',
  '--ts-var-liveboard-group-background': EMBED_APP_BACKGROUND,
  '--ts-var-nav-background': EMBED_APP_BACKGROUND,
  '--ts-var-search-bar-background': '#ffffff',
  '--ts-var-search-auto-complete-background': '#ffffff',
  '--ts-var-search-navigation-button-background': '#F3F4F6',
  '--ts-var-search-bar-navigation-help-text-background': '#F9FAFB',
  '--ts-var-spotter-input-background': '#ffffff',
  '--ts-var-spotter-prompt-background': '#FFF5F7',
  '--ts-var-answer-data-panel-background-color': '#ffffff',
  // Filter chips — styled to brand pink palette
  '--ts-var-chip-background': BRAND_PINK_LIGHT,
  '--ts-var-chip-color': BRAND_PINK,
  '--ts-var-chip-border-radius': '20px',
  '--ts-var-chip--active-background': BRAND_PINK,
  '--ts-var-chip--active-color': '#ffffff',
  '--ts-var-chip--hover-background': BRAND_PINK_HOVER,
  '--ts-var-chip--hover-color': BRAND_PINK,
  // Parameter chips & header text
  '--ts-var-parameter-chip-text-color': BRAND_PINK,
  '--ts-var-liveboard-header-font-color': '#1C1C1E',
};

/**
 * SDK init — NoAuth assumes the user is already logged in to ThoughtSpot in the browser.
 */
export function buildThoughtSpotEmbedConfig(): EmbedConfig {
  return {
    thoughtSpotHost,
    authType: AuthType.None,
    suppressSearchEmbedBetaWarning: true,
    customizations: {
      iconSpriteUrl: DATABOT_ICON_URL,
      style: {
        customCSS: {
          variables: embedStyleVariables,
          rules_UNSTABLE: {
            // Reduce compact filter bar vertical padding
            '[class*="filterRow"]':        { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
            '[class*="filter-row"]':       { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
            '[class*="compactHeader"]':    { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
            '[class*="compact-header"]':   { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
            '[class*="liveboardFilter"]':  { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
            '[class*="FilterBar"]':        { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
          },
        },
      },
      content: {
        strings: {
          Spotter: 'Muse',
          'AI Highlights': 'Highlights',
          Pin: 'Pin',
        },
      },
    },
  };
}
